:root {
  --tag-bg: #fdf6ee;
  --tag-border: #c8a87a;
  --header-bg: #3b2314;
  --header-text: #f5ddb0;
  --badge-bg: #b85c1a;
  --badge-text: #fff8ee;
  --piece-id-color: #c8a87a;
  --vessel-neck: #e8943a;
  --vessel-body: #d4701a;
  --vessel-base: #3b2314;
  --ring-color: #e8943a;
  --piece-name-color: #3b2314;
  --piece-type-color: #7a4a20;
  --label-color: #b07040;
  --value-color: #3b2314;
  --divider-color: #e0c090;
  --footer-bg: #f0e4cc;
  --status-dot-color: #c8501a;
  --status-text-color: #b85c1a;
  --fired-date-color: #7a4a20;
  --artist-name-color: #3b2314;
}

.piece-tag {
  width: 460px;
  background-color: var(--tag-bg);
  border: 2px solid var(--tag-border);
  border-radius: 10px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.tag-header {
  background-color: var(--header-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 14px;
}

.studio-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  padding: 3px 8px;
  border-radius: 3px;
  text-transform: uppercase;
}

.piece-id {
  color: var(--piece-id-color);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
}

.tag-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  flex: 1;
}

.piece-visual {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 16px 12px;
  gap: 10px;
  border-right: 1px solid var(--divider-color);
  width: 120px;
  flex-shrink: 0;
}

.vessel-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  margin: 0;
}

.vessel-neck {
  width: 18px;
  height: 26px;
  background-color: var(--vessel-neck);
  border-radius: 4px 4px 0 0;
  border: 1.5px solid var(--vessel-base);
  border-bottom: none;
}

.vessel-body {
  width: 58px;
  height: 54px;
  background-color: var(--vessel-body);
  border-radius: 50% 50% 40% 40%;
  border: 1.5px solid var(--vessel-base);
}

.vessel-base {
  width: 36px;
  height: 8px;
  background-color: var(--vessel-base);
  border-radius: 0 0 4px 4px;
}

.heat-rings {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.ring {
  display: block;
  border: 1.5px solid var(--ring-color);
  border-radius: 50%;
  opacity: 0.7;
}

.r1 { width: 32px; height: 10px; }
.r2 { width: 24px; height: 8px; opacity: 0.5; }
.r3 { width: 16px; height: 6px; opacity: 0.3; }

.piece-details {
  flex: 1;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.piece-name {
  font-size: 18px;
  font-weight: 800;
  color: var(--piece-name-color);
  margin: 0;
  line-height: 1.1;
}

.piece-type {
  font-size: 11px;
  font-weight: 600;
  color: var(--piece-type-color);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin: 0;
}

.spec-list {
  list-style: none;
  margin: 4px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 10px;
}

.spec-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.spec-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--label-color);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.spec-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--value-color);
}

.tag-footer {
  background-color: var(--footer-bg);
  border-top: 1px solid var(--divider-color);
  padding: 8px 14px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.artist-row {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.artist-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--label-color);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.artist-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--artist-name-color);
}

.footer-divider {
  width: 1px;
  height: 28px;
  background-color: var(--divider-color);
  margin: 0 4px;
}

.status-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--status-dot-color);
  flex-shrink: 0;
}

.status-text {
  font-size: 10px;
  font-weight: 800;
  color: var(--status-text-color);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.fired-date {
  font-size: 11px;
  font-weight: 600;
  color: var(--fired-date-color);
  margin-left: auto;
}
